// Generated from the author images used by 关于作者文案.md.
// Keep these as data URIs so published installs do not depend on a local vault asset path.
const EMBEDDED_AUTHOR_ASSETS: Record<string, string> = {
  "tip-notebook-cover.png": "data:image/png;base64,",
  "扫码_搜索联合传播样式-标准色版.png": "data:image/png;base64,",
};

export function resolveEmbeddedAuthorAsset(target: string): string | null {
  const normalized = target.trim().split("/").pop() ?? target.trim();
  return EMBEDDED_AUTHOR_ASSETS[normalized] ?? null;
}
